  dbr:Peter_the_Younger dbp:mother ?mother .
  {
    ?mother dbp:father ?maternalGrandfather .
  } UNION {
    ?mother dbo:father ?maternalGrandfather .
  }
  OPTIONAL { ?maternalGrandfather rdfs:label ?mfLabel . FILTER(langMatches(lang(?mfLabel), "en")) }
}

